539	    /**
540	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
541	     * cannot form a valid E.164 number.
542	     *
543	     * <p>A leading '+' and country code are kept when present; otherwise country code
544	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
545	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
546	     * carry 8 to 15 digits after the '+', and — for a recognised country calling code —
547	     * exactly the national-digit count that code requires (see
548	     * {@link Owner#hasValidNationalLength}); otherwise it is rejected as invalid.
549	     */
550	    private String toE164(String telephone) {
551	        if (telephone == null) {
552	            return null;
553	        }
554	        boolean hasCountryCode = telephone.trim().startsWith("+");
555	        String digits = telephone.replaceAll("\\D", "");
556	        String e164;
557	        if (hasCountryCode) {
558	            e164 = digits;
559	        } else {
560	            if (digits.startsWith("0")) {
561	                digits = digits.substring(1);
562	            }
563	            e164 = "61" + digits;
564	        }
565	        if (e164.length() < 8 || e164.length() > 15) {
566	            return null;
567	        }
568	        if (!Owner.hasValidNationalLength(e164)) {
569	            return null;
570	        }
571	        return "+" + e164;
572	    }
573	
574	    /**
575	     * Whether the candidate owner belongs to a household that already exists, and so must be
576	     * rejected with {@code 409 Conflict} unless it declares {@code sharesHousehold}. The household
577	     * is keyed by the deterministic {@link #householdId(Owner) householdId} (derived from lastName
578	     * and postcode), so any existing owner carrying the same householdId means this owner is a
579	     * second member of an already-registered household. Two owners sharing a lastName and postcode
580	     * are therefore the same household: the second is a household duplicate.
581	     */
582	    private boolean isHouseholdDuplicate(Owner owner) {
583	        String householdId = owner.getHouseholdId();
584	        if (householdId == null) {
585	            return false;
586	        }
587	        return activeOwners().stream()
588	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
589	    }
590	
591	    /**
592	     * Normalize an owner's name for household comparison: trim, collapse internal whitespace runs
593	     * to a single space and lower-case. A null value normalizes to the empty string.
594	     */
595	    private String normalizeName(String value) {
596	        if (value == null) {
597	            return "";
598	        }
599	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
600	    }
601	
602	    /**
603	     * A stable shared identifier for the household an owner belongs to, derived deterministically
604	     * from its lastName and postcode. The lastName is normalized (case-insensitive,
605	     * whitespace-collapsed) before hashing, so every owner sharing the same lastName and postcode is
606	     * assigned the same value regardless of the order in which they are created. Formatted as the
607	     * first 12 upper-case hex characters of the SHA-256 of {@code '<normalizedLastName>|<postcode>'}
608	     * (an absent postcode contributes the empty string).
609	     */
610	    private String householdId(Owner owner) {
611	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
612	        String key = normalizeName(owner.getLastName()) + "|" + postcode;
613	        return shaHexUpper(key).substring(0, 12);
614	    }
615	
616	    /**
617	     * The SHA-256 digest of {@code input}'s UTF-8 bytes, rendered as an upper-case hexadecimal
618	     * string (two hex characters per digest byte, so 64 characters in all). This is the single
619	     * place the hashing-and-hex-encoding is performed; callers that need a shorter opaque token
620	     * take a prefix of the result (e.g. {@link #householdId} keeps the first 12 characters and
621	     * {@link #customerCode} keeps the first 8).
622	     */
623	    private String shaHexUpper(String input) {
624	        try {
625	            byte[] digest = MessageDigest.getInstance("SHA-256")
626	                .digest(input.getBytes(StandardCharsets.UTF_8));
627	            StringBuilder sb = new StringBuilder(digest.length * 2);
628	            for (byte b : digest) {
629	                sb.append(String.format("%02x", b));
630	            }
631	            return sb.toString().toUpperCase();
632	        }
633	        catch (NoSuchAlgorithmException e) {
634	            throw new IllegalStateException("SHA-256 not available", e);
635	        }
636	    }
