345	    /**
346	     * The Luhn check digit (a single digit, {@code 0}-{@code 9}) over the decimal digits
347	     * contained in {@code value}. Reading the digits right to left, every second one is
348	     * doubled (subtracting 9 whenever doubling yields a value above 9); the transformed
349	     * digits are summed, and the check digit is the amount that must be added to that sum to
350	     * reach the next multiple of ten. Any non-digit character in {@code value} is ignored, so
351	     * the digit is taken over exactly the digits the string carries.
352	     */
353	    private static int luhnCheckDigit(String value) {
354	        int sum = 0;
355	        boolean doubling = true;
356	        for (int i = value.length() - 1; i >= 0; i--) {
357	            char c = value.charAt(i);
358	            if (c < '0' || c > '9') {
359	                continue;
360	            }
361	            int digit = c - '0';
362	            if (doubling) {
363	                digit *= 2;
364	                if (digit > 9) {
365	                    digit -= 9;
366	                }
367	            }
368	            sum += digit;
369	            doubling = !doubling;
370	        }
371	        return (10 - (sum % 10)) % 10;
372	    }
