11	/**
12	 * Starting from Spring Boot 2, if Spring Security is present, endpoints are secured by default
13	 * using Spring Security’s content-negotiation strategy.
14	 */
15	@Configuration
16	@ConditionalOnProperty(name = "petclinic.security.enable", havingValue = "false")
17	public class DisableSecurityConfig {
